use std::{fs, io::{Read,Write},path::Path};
unsafe extern "C" { fn unge_add(a:i32,b:i32)->i32; }
fn main() {
    assert_eq!(unsafe { unge_add(20,22) },42);
    let folder=Path::new(env!("CARGO_MANIFEST_DIR"));
    let mut count=0;
    for n in [0,1,7,511,512,513,32767,32768,32769,65536,65537] {
        let expected=fs::read(folder.join(n.to_string())).unwrap();
        for mode in ["gzip","zlib","deflate"] {
            let input=fs::read(folder.join(format!("{n}.py.{mode}"))).unwrap();
            let mut reader:Box<dyn Read> = match mode { "gzip"=>Box::new(flate2::read::GzDecoder::new(&input[..])),"zlib"=>Box::new(flate2::read::ZlibDecoder::new(&input[..])),_=>Box::new(flate2::read::DeflateDecoder::new(&input[..])) };
            let mut output=Vec::new();let mut buffer=[0;3];loop {let read=reader.read(&mut buffer).unwrap();if read==0{break;}output.extend_from_slice(&buffer[..read]);}assert_eq!(output,expected);
            let bytes=match mode {"gzip"=>{let mut e=flate2::write::GzEncoder::new(Vec::new(),flate2::Compression::default());for chunk in expected.chunks(7){e.write_all(chunk).unwrap();}e.flush().unwrap();e.finish().unwrap()},"zlib"=>{let mut e=flate2::write::ZlibEncoder::new(Vec::new(),flate2::Compression::default());for chunk in expected.chunks(7){e.write_all(chunk).unwrap();}e.flush().unwrap();e.finish().unwrap()},_=>{let mut e=flate2::write::DeflateEncoder::new(Vec::new(),flate2::Compression::default());for chunk in expected.chunks(7){e.write_all(chunk).unwrap();}e.flush().unwrap();e.finish().unwrap()}};
            fs::write(folder.join(format!("{n}.rust.{mode}")),bytes).unwrap();count+=1;
        }
    }
    let mut encoder=flate2::write::DeflateEncoder::new(Vec::new(),flate2::Compression::default());encoder.write_all(b"test truncated stream").unwrap();let bytes=encoder.finish().unwrap();
    for end in 0..bytes.len(){let mut decoder=flate2::write::DeflateDecoder::new(Vec::new());decoder.write_all(&bytes[..end]).unwrap();assert_eq!(decoder.finish().unwrap_err().kind(),std::io::ErrorKind::UnexpectedEof);}
    for _ in 0..1000 {let id=uuid::Uuid::new_v4();assert_eq!(id.get_version_num(),4);let text=serde_json::to_string(&id).unwrap();assert_eq!(serde_json::from_str::<uuid::Uuid>(&text).unwrap(),id);assert_eq!(id.to_string().parse::<uuid::Uuid>().unwrap(),id);}
    println!("{count} Python-to-Rust compression cases, truncation rejection, 1000 UUID v4/serde roundtrips, C compile/link/call -> 42: passed");
}
